5	
6	const SPHINX = "sphinx";
7	const BASE_SCORE = 1;
8	const FREE_TYPE_ALLOWANCE = 3;
9	const MINIMUM_BONUS = 1;
10	const BONUS_PER_EXTRA_TYPE = 2;
11	
12	const countSphinxes = (army: Card[]): number =>
13	  army.filter((card) => card.monster === SPHINX).length;
14	
15	const countTypesOtherThanSphinx = (army: Card[]): number => {
16	  const allTypes = new Set(army.map((card) => card.monster)).size;
17	  const isOnlySphinx = countSphinxes(army) === 1;
18	  return isOnlySphinx ? allTypes - 1 : allTypes;
19	};
20	
21	const varietyBonus = (typeCount: number): number =>
22	  typeCount > FREE_TYPE_ALLOWANCE
23	    ? BONUS_PER_EXTRA_TYPE * (typeCount - FREE_TYPE_ALLOWANCE)
24	    : MINIMUM_BONUS;
25	
26	const scoreOneSphinx = (army: Card[]): number =>
27	  BASE_SCORE + varietyBonus(countTypesOtherThanSphinx(army));
28	
29	export const scoreArmy = (army: Card[]): number =>
30	  countSphinxes(army) * scoreOneSphinx(army);
31

